<?phpnamespace App\Livewire\Admin\Projects\Skills\Options;use Illuminate\Contracts\Foundation\Application;use Illuminate\Contracts\View\Factory;use Illuminate\Contracts\View\View;use Livewire\Component;use App\Models\Category;use WireUi\Traits\Actions;use App\Models\ProjectSkill;use Livewire\WithFileUploads;use Livewire\Attributes\Layout;use Jantinnerezo\LivewireAlert\LivewireAlert;use Artesaos\SEOTools\Traits\SEOTools as SEOToolsTrait;use App\Http\Validators\Admin\Projects\Skills\CreateValidator;class CreateComponent extends Component{    use SEOToolsTrait, WithFileUploads, LivewireAlert, Actions;    public $name = [];    public $category;    /** * Render component *     * @return Application|Factory|View|\Illuminate\Foundation\Application     */    #[Layout('components.layouts.admin-app')]    public function render(): Application|Factory|View|\Illuminate\Foundation\Application    {        // Seo        $this->seo()->setTitle( setSeoTitle(__('messages.t_create_skills'), true) );        $this->seo()->setDescription( settings('seo')->description );        return view('livewire.admin.projects.skills.options.create', [            'categories' => $this->categories        ]);    }    /**     * Get categories     *     * @return object     */    public function getCategoriesProperty()    {        return Category::orderBy('id', 'asc')->withTranslation()->get();    }    /**     * Create new skills     *     * @return void     */    public function create()    {        try {            // Validate form            CreateValidator::validate($this);            // Explode names by new line            $enName = $this->name['en'];            $slug = generate_slug($enName) . '-' . $this->category;            $skill = new ProjectSkill();            $skill->category_id = $this->category;            $skill->uid = uid();            $skill->slug = $slug;            $skill->save();            foreach (supported_languages() as $language) {                $skill->translateOrNew($language->language_code)->name  = $this->name[$language->language_code];            }            $skill->save();            // Success            $this->alert(                'success',                __('messages.t_success'),                livewire_alert_params( __('messages.t_toast_operation_success') )            );            // Refresh the page            $this->dispatch('refresh');        } catch (\Illuminate\Validation\ValidationException $e) {            // Validation error            $this->alert(                'error',                __('messages.t_error'),                livewire_alert_params( __('messages.t_toast_form_validation_error'), 'error' )            );            throw $e;        } catch (\Throwable $th) {            // Error            $this->alert(                'error',                __('messages.t_error'),                livewire_alert_params( $th->getMessage(), 'error' )            );        }    }}